const { chromium } = require('playwright');
const axe = require('axe-core');
const fs = require('fs');
const path = require('path');

(async () => {
    let browser;
    try {
        browser = await chromium.launch();
    } catch (e) {
        console.error("BROWSER_MISSING");
        process.exit(1);
    }
    const page = await browser.newPage();
    const html = fs.readFileSync('index.html', 'utf8');
    const css = fs.readFileSync('styles.css', 'utf8');
    const js = fs.readFileSync('script.js', 'utf8');

    // Serve HTML
    await page.setContent(html);

    // Inject CSS
    await page.addStyleTag({ content: css });

    // Inject JS
    await page.addScriptTag({ content: js });

    // Inject axe
    await page.addScriptTag({ path: require.resolve('axe-core') });

    const results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }));

    await browser.close();
    process.exit(wcag.length > 0 ? 1 : 0);
})();

