    display: grid;
    gap: var(--spacing-lg);
}

@media (min-width: 640px) {
    .deals-grid { grid-template-columns: repeat(2, 1fr); }
    .products-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 900px) {
    .deals-grid { grid-template-columns: repeat(3, 1fr); }
    .products-grid { grid-template-columns: repeat(4, 1fr); }
    .editorial-grid { grid-template-columns: repeat(2, 1fr); }
}

/* Header & Nav */
.site-header {
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-secondary);
    position: sticky;
    top: 0;
    z-index: 10;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 70px;
}

.brand a {
    font-size: 1.5rem;
    font-weight: 700;
    text-decoration: none;
}

.main-nav {
    display: none;
}

@media (min-width: 768px) {
    .mobile-menu-toggle {
        display: none;
    }

    .main-nav {
        display: block;
    }

    .main-nav ul {
        display: flex;
        gap: var(--spacing-lg);
    }

    .main-nav a {
        font-weight: 500;
        color: var(--color-text-light);
    }

    .main-nav a:hover,
    .main-nav a:focus {
        color: var(--color-primary);
        text-decoration: none;
    }
}

.mobile-menu-toggle {
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-sm);
    color: var(--color-primary);
}

.header-actions {
    display: flex;
    align-items: center;
}

.cart-btn {
    background: none;
    border: none;
    cursor: pointer;
    position: relative;
    padding: var(--spacing-sm);
    color: var(--color-primary);
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background: var(--color-accent);
    color: white;
    font-size: 0.75rem;
    font-weight: bold;
    border-radius: 50%;
    width: 18px;
    height: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Mobile Nav Overlay (JS controlled) */
.main-nav.is-open {
    display: block;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-secondary);
    padding: var(--spacing-md);
    box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1);
}

.main-nav.is-open ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.main-nav.is-open a {
    display: block;
    padding: var(--spacing-sm) 0;
    font-weight: 500;
}

/* Hero */
.hero {
    background: var(--color-bg-alt);
    padding: var(--spacing-xl) 0;
    text-align: center;
}

.hero h1 {
    font-size: clamp(2rem, 5vw, 3.5rem);
    line-height: 1.2;
    margin-bottom: var(--spacing-md);
}

.hero p {
    font-size: 1.125rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-lg);
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* Components */
.button {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    padding: 0.75rem 1.5rem;
