:root {
    --color-primary: #111827;
    --color-primary-hover: #374151;
    --color-secondary: #f3f4f6;
    --color-text: #1f2937;
    --color-text-light: #4b5563;
    --color-bg: #ffffff;
    --color-bg-alt: #f9fafb;
    --color-accent: #dc2626;
    --color-focus: #2563eb;

    --font-main: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;

    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 2rem;
    --spacing-xl: 4rem;

    --border-radius: 8px;
    --transition: 0.2s ease-in-out;
}

/* Reset & Base */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-main);
    color: var(--color-text);
    background-color: var(--color-bg);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

img {
    max-width: 100%;
    display: block;
}

a {
    color: var(--color-primary);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

ul {
    list-style: none;
}

/* Accessibility Utilities */
.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

:focus-visible {
    outline: 3px solid var(--color-focus);
    outline-offset: 2px;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: white;
    padding: var(--spacing-sm) var(--spacing-md);
    z-index: 100;
    transition: top var(--transition);
}

.skip-link:focus {
    top: 0;
}

/* Layout */
.container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

.section {
    padding: var(--spacing-xl) 0;
}

.grid {
    display: grid;
    gap: var(--spacing-lg);
}

@media (min-width: 640px) {
    .deals-grid { grid-template-columns: repeat(2, 1fr); }
    .products-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 900px) {
    .deals-grid { grid-template-columns: repeat(3, 1fr); }
    .products-grid { grid-template-columns: repeat(4, 1fr); }
    .editorial-grid { grid-template-columns: repeat(2, 1fr); }
}

/* Header & Nav */
.site-header {
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-secondary);
    position: sticky;
    top: 0;
    z-index: 10;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 70px;
}

.brand a {
    font-size: 1.5rem;
    font-weight: 700;
    text-decoration: none;
}

.main-nav {
    display: none;
}

@media (min-width: 768px) {
    .mobile-menu-toggle {
        display: none;
    }

    .main-nav {
        display: block;
    }

    .main-nav ul {
        display: flex;
        gap: var(--spacing-lg);
    }

    .main-nav a {
        font-weight: 500;
        color: var(--color-text-light);
    }

    .main-nav a:hover,
    .main-nav a:focus {
        color: var(--color-primary);
        text-decoration: none;
    }
}

.mobile-menu-toggle {
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-sm);
    color: var(--color-primary);
}

.header-actions {
    display: flex;
    align-items: center;
}

.cart-btn {
    background: none;
    border: none;
    cursor: pointer;
    position: relative;
    padding: var(--spacing-sm);
    color: var(--color-primary);
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background: var(--color-accent);
    color: white;
    font-size: 0.75rem;
    font-weight: bold;
    border-radius: 50%;
    width: 18px;
    height: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Mobile Nav Overlay (JS controlled) */
.main-nav.is-open {
    display: block;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-secondary);
    padding: var(--spacing-md);
    box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1);
}

.main-nav.is-open ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.main-nav.is-open a {
    display: block;
    padding: var(--spacing-sm) 0;
    font-weight: 500;
}

/* Hero */
.hero {
    background: var(--color-bg-alt);
    padding: var(--spacing-xl) 0;
    text-align: center;
}

.hero h1 {
    font-size: clamp(2rem, 5vw, 3.5rem);
    line-height: 1.2;
    margin-bottom: var(--spacing-md);
}

.hero p {
    font-size: 1.125rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-lg);
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* Components */
.button {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    padding: 0.75rem 1.5rem;
    border-radius: var(--border-radius);
    font-weight: 600;
    cursor: pointer;
    transition: background var(--transition);
    border: 1px solid transparent;
}

.button.primary {
    background-color: #111827;
    color: white;
    text-decoration: none;
}

.button.primary:hover {
    background-color: var(--color-primary-hover);
}

.add-to-cart {
    width: 100%;
    background: var(--color-bg);
    border: 1px solid var(--color-primary);
    color: var(--color-primary);
    margin-top: var(--spacing-md);
}

.add-to-cart:hover {
    background: var(--color-secondary);
}

.card {
    background: var(--color-bg);
    border-radius: var(--border-radius);
    overflow: hidden;
    border: 1px solid var(--color-secondary);
    transition: transform var(--transition);
    position: relative;
}

.card:hover {
    transform: translateY(-4px);
    box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
}

.card a::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
}

.add-to-cart {
    position: relative;
    z-index: 2;
}

.placeholder-img {
    background: var(--color-secondary);
    aspect-ratio: 4/5;
    width: 100%;
}

.editorial-card .placeholder-img {
    aspect-ratio: 16/9;
}

.card-content {
    padding: var(--spacing-md);
}

.card-title {
    font-size: 1.125rem;
    margin-bottom: var(--spacing-xs);
}

.card-title a {
    color: var(--color-text);
    text-decoration: none;
}

.price {
    font-weight: 500;
}

.price s {
    color: var(--color-text-light);
    margin-right: var(--spacing-xs);
}

.price strong {
    color: var(--color-accent);
}

.badge.sale {
    display: inline-block;
    background: var(--color-accent);
    color: white;
    font-size: 0.75rem;
    font-weight: bold;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    margin-bottom: var(--spacing-sm);
}

/* Sections */
.section h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-lg);
    text-align: center;
}

.editorial-card p {
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
}

.read-more {
    font-weight: 600;
    color: var(--color-focus);
}

/* Footer */
.site-footer {
    background: var(--color-bg-alt);
    padding: var(--spacing-xl) 0 var(--spacing-lg);
    border-top: 1px solid var(--color-secondary);
}

.footer-content {
    display: grid;
    gap: var(--spacing-lg);
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    margin-bottom: var(--spacing-xl);
}

.footer-section h2 {
    font-size: 1.125rem;
    margin-bottom: var(--spacing-md);
}

.footer-section ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-light);
}

.footer-section a:hover {
    color: var(--color-primary);
}

.footer-bottom {
    text-align: center;
    color: var(--color-text-light);
    font-size: 0.875rem;
    border-top: 1px solid var(--color-secondary);
    padding-top: var(--spacing-lg);
